#!/usr/bin/env python3
"""Build the candidate comparison and exact generation/inspection receipts."""
import hashlib,html,json,os,subprocess
from pathlib import Path
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[4];HOME=Path(__file__).resolve().parent
STORY=ROOT/'stories/lion_and_mouse_v6'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return str(p.relative_to(ROOT))
def link(p):return os.path.relpath(p,HOME)
def main():
 refs=json.loads((HOME/'inputs.json').read_text())
 for r in refs:assert sha(ROOT/r['path'])==r['sha256']
 source=ROOT/refs[0]['path'];adopted=json.loads((HOME/'lighting_receipt.json').read_text()).get('active_selection_changed',False);old=ROOT/refs[3]['path'];candidate=ROOT/'character/characters/lion_and_mouse_v6/Milo/canonical/full-body_milo_neutral_pose_r03_candidate.png'
 new=Image.open(candidate);assert new.mode=='RGBA';alpha=new.getchannel('A');assert alpha.getextrema()==(0,255);bbox=alpha.point(lambda a:255 if a>=8 else 0).getbbox();assert bbox and bbox[0]>0 and bbox[1]>0 and bbox[2]<new.width and bbox[3]<new.height
 # Presentation crops only, no edits to reference/production image bytes.
 board=Image.new('RGB',(1500,760),'#343434');draw=ImageDraw.Draw(board)
 items=[('Preferred scene Milo',Image.open(source).convert('RGB').crop((610,295,1045,790))),('Current r02 master',Image.open(old).convert('RGBA')),('Proposed r03 master',new)]
 for i,(title,im) in enumerate(items):
  if im.mode=='RGBA':
   box=im.getchannel('A').point(lambda a:255 if a>=8 else 0).getbbox();im=im.crop(box);panel=Image.new('RGBA',im.size,(95,95,95,255));panel.alpha_composite(im);im=panel.convert('RGB')
  im=im.resize((round(im.width*530/im.height),530),Image.Resampling.LANCZOS);assert im.width<=490;board.paste(im,(i*500+(500-im.width)//2,85));draw.text((i*500+15,20),title,fill='white')
 board.save(HOME/'identity_comparison.jpg',quality=96)
 receipt={'schema':'feltwillow.milo-scene04-identity-proposal.v1','story':'lion_and_mouse_v6','status':'prepared_pending_owner_selection','owner_direction':'Use the Milo in s04x_p01_r01_candidate.png to prepare a new version of Milo; investigate the circular bright facial patch in s04_p02_r13_candidate.png.','source_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'tool':'built-in image_gen','canonical_candidate':{'path':rel(candidate),'sha256':sha(candidate),'dimensions':list(new.size),'transparent_background':True,'alpha_bbox_at_threshold_8':list(bbox),'raw_alpha_bbox':list(alpha.getbbox()),'status':'candidate_not_active_identity_authority','prompt_path':rel(HOME/'canonical_prompt.txt'),'prompt_sha256':sha(HOME/'canonical_prompt.txt'),'ordered_model_attachments':[{'role':'owner_preferred_identity_example','path':refs[0]['path'],'sha256':refs[0]['sha256']}],'previous_master_used_as_generation_reference':False,'inspection':'One complete mouse; both ears, tail and feet inside frame; cream inset narrower than r02; soft muzzle and moss-green eyes; neutral broad lighting; no visible teeth. Source scene pose and sunset light are intentionally not copied as canonical requirements.'},'lighting_repair':{'receipt':rel(HOME/'lighting_receipt.json'),'prompt_path':rel(HOME/'lighting_prompt.txt'),'prompt_sha256':sha(HOME/'lighting_prompt.txt'),'ordered_model_attachments':[{'role':'exact_lighting_edit_target','path':refs[1]['path'],'sha256':refs[1]['sha256']},{'role':'lighting_material_example_only','path':refs[2]['path'],'sha256':refs[2]['sha256']}],'status':'adopted_owner_directed_repair' if adopted else 'candidate_not_adopted','inspection':'Native actor before/after inspection: pale facial disc reduced through continuous illumination; source pose, size, expression detail and all exterior pixels preserved. Scene example has a different camera and is lighting guidance only.'},'active_canonical':refs[3],'active_keyframes_modified':adopted,'production_approval_inferred':False,'duplicated_comparison_in_user_message':'Second pair names s04_p02_r13 twice; clarification requested asynchronously. No unidentified second comparison was assumed.'}
 (HOME/'proposal.json').write_text(json.dumps(receipt,indent=2)+'\n')
 repair=json.loads((HOME/'lighting_receipt.json').read_text());fixed=ROOT/repair['output_path'];current=ROOT/repair['source_path']
 parts=['<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Milo identity and lighting candidates</title><style>body{background:#242424;color:#eee;font:17px/1.5 system-ui;margin:25px}a{color:#a7d4ff}img{max-width:100%;height:auto}.pair{display:flex;gap:15px}.pair a{width:50%}.master{background:#555;max-height:850px}section{margin:35px 0}</style><h1>Milo: proposed identity master and face-lighting repair</h1><p>New candidates prepared from the owner\'s Scene 04 preference. The new r03 identity master is a candidate. The face-lighting repair is active as s04_p02_r14; the previous r13 is preserved. Current identity authority remains r02. No identity-family rollout or technical approval is inferred.</p><section><h2>Identity comparison</h2><p>Left: preferred scene Milo. Middle: current r02. Right: proposed r03 under neutral lighting. Compare ear/head shape, eye whites, muzzle, torso and felt texture. The old master was not attached to the new generation.</p><a href="identity_comparison.jpg"><img src="identity_comparison.jpg"></a><p><a href="'+link(source)+'">Preferred source, full resolution</a> · <a href="'+link(candidate)+'">New transparent master, full resolution</a> · <a href="'+link(old)+'">Current master</a></p><a href="'+link(candidate)+'"><img class="master" src="'+link(candidate)+'"></a></section><section><h2>s04_p02 face-lighting repair</h2><p>The previous frozen face ellipse kept different lighting from the surrounding character. The new candidate transfers only a smooth illumination field to the original actor pixels, including the face. Model geometry is excluded; all scenery stays exact. Left: previous r13. Right: active r14 repair.</p><a href="lighting_detail_comparison.jpg"><img src="lighting_detail_comparison.jpg"></a><div class="pair"><a href="'+link(current)+'"><img src="'+link(current)+'"></a><a href="'+link(fixed)+'"><img src="'+link(fixed)+'"></a></div></section><p>Exact prompts, source hashes, raw lighting suggestion, mask and processing parameters are preserved in this folder. The second comparison in the request repeated the same filename and is awaiting clarification.</p>']
 (HOME/'owner_review.html').write_text('\n'.join(parts));print(json.dumps({'new_master':rel(candidate),'size':list(new.size),'alpha_bbox':bbox,'lighting_repair':rel(fixed)}))
if __name__=='__main__':main()
